const baseUrl = String(env.get('TRACE_API_URL') || '').replace(/\/$/, '');
const token = String(env.get('PLC_INTERNAL_TOKEN') || '');
if (!baseUrl || !token) return null;
msg.url = `${baseUrl}/api/equipamentos_gateway.php`;
msg.method = 'GET';
msg.headers = { 'X-Internal-Token': token };
return msg;

const equipment = Array.isArray(msg.payload?.data) ? msg.payload.data : [];
const baseUrl = String(env.get('TRACE_API_URL') || '').replace(/\/$/, '');
const token = String(env.get('PLC_INTERNAL_TOKEN') || '');
if (!equipment.length || !baseUrl || !token) return null;
equipment.forEach(item => node.send({ ...msg, url: `${baseUrl}/api/device_heartbeat.php`, method: 'POST', headers: { 'X-Internal-Token': token, 'Content-Type': 'application/json' }, payload: { equipment_id: Number(item.id), device_type: 'CLP', status: 'ONLINE', details: { source: 'node-red', heartbeat_interval_ms: 1000 } } }));
return null;

const baseUrl = String(env.get('TRACE_API_URL') || '').replace(/\/$/, '');
const token = String(env.get('PLC_INTERNAL_TOKEN') || '');
if (!baseUrl || !token) return null;
msg.url = `${baseUrl}/api/equipamentos_gateway.php`;
msg.method = 'GET';
msg.headers = { 'X-Internal-Token': token };
return msg;

const equipment = Array.isArray(msg.payload?.data) ? msg.payload.data : [];
const baseUrl = String(env.get('TRACE_API_URL') || '').replace(/\/$/, '');
const token = String(env.get('PLC_INTERNAL_TOKEN') || '');
if (!equipment.length || !baseUrl || !token) return null;
equipment.forEach(item => node.send({ ...msg, url: `${baseUrl}/api/plc_gateway.php`, method: 'POST', headers: { 'X-Internal-Token': token, 'Content-Type': 'application/json' }, payload: { action: 'CLAIM', equipment_id: Number(item.id) } }));
return null;

const response = msg.payload && (msg.payload.data || msg.payload);
if (!response || !response.id) return null;
const allowed = ['REVERSAO_ATIVAR', 'REVERSAO_DESATIVAR'];
const status = allowed.includes(String(response.command || '')) ? 'REJEITADO' : 'ERRO';
const reason = status === 'REJEITADO'
    ? 'Mapa de I/O do CLP ainda não aprovado; nenhuma escrita foi executada.'
    : 'Comando não suportado pelo gateway local.';
const baseUrl = String(env.get('TRACE_API_URL') || '').replace(/\/$/, '');
const token = String(env.get('PLC_INTERNAL_TOKEN') || '');
msg.url = `${baseUrl}/api/plc_gateway.php`;
msg.method = 'POST';
msg.headers = {
    'X-Internal-Token': token,
    'Content-Type': 'application/json'
};
msg.payload = { action: 'COMPLETE', request_id: Number(response.id), status, message: reason };
return msg;
